function JONES_GENERATOR(A, X):
    I <- identity matrix of size(X)
    sigma     <- A * I + A^{-1} * X        # jonesOp
    sigma_inv <- A^{-1} * I + A * X         # jonesInv
    return (sigma, sigma_inv)

function VERIFY_INVERSE(A, X, tol):
    (sigma, sigma_inv) <- JONES_GENERATOR(A, X)
    return  norm(sigma * sigma_inv - I) < tol
        and norm(sigma_inv * sigma - I) < tol

