function TL_GENERATORS(A, n):
    q <- -A^2
    U <- 4x4 zero matrix              # sites (i, i+1), basis |00>,|01>,|10>,|11>
    U[01,01] <- q ; U[01,10] <- -1
    U[10,01] <- -1 ; U[10,10] <- 1/q
    gens <- []
    for i in 0 .. n-2:
        L <- I_{2^i} ; R <- I_{2^{n-i-2}}
        gens.append( L (x) U (x) R )    # Kronecker products
    return gens
